	for _, value := range []string{req.Smoke.Level, req.Smoke.Suite, req.Smoke.Test} {
		if value != "" {
			selected++
		}
	}
	if selected > 1 {
		return req, jsonOut, fmt.Errorf("choose only one of --level, --suite, or --test")
