type resumeRuntime struct {
	mu       sync.Mutex
	requests []pruntime.Request
	failTask string
}

func (r *resumeRuntime) StartRun(_ context.Context, req pruntime.Request) (pruntime.Result, error) {
	r.mu.Lock()
	r.requests = append(r.requests, req)
	task := req.Metadata["task"]
	fail := r.failTask != "" && task == r.failTask
	r.mu.Unlock()
	if fail {
		return pruntime.Result{RunID: "run-" + task, Status: "failed"}, context.DeadlineExceeded
	}
	return pruntime.Result{RunID: "run-" + task, SessionID: "sess-" + task, Status: "success", Artifacts: []pruntime.Artifact{{ID: "ev-" + task, Kind: "test", Description: "verified"}}}, nil
}

func (r *resumeRuntime) snapshot() []pruntime.Request {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]pruntime.Request(nil), r.requests...)
}

func twoTaskPlan(t *testing.T, sp Sprint) {
	t.Helper()
	plan := strings.Replace(validPlan(), "## Evidence Checklist", "- [ ] Task 2: Verify second task for Decision 1 / AC-01\n  > Executes: Decision 1, AC-01\n  - [ ] Verification expectation: go test ./...\n\n## Evidence Checklist", 1)
	writeFileContent(t, sp.Path, plan, "plan.md")
}

// R1: stale running record is recovered to failed and retried on --resume.
func TestScratchResumeRecoversStaleRunningAndRetries(t *testing.T) {
	runtime := &resumeRuntime{}
	root, sp, service := executePersistenceFixture(t, runtime)
	twoTaskPlan(t, sp)

	_, tasks, _, _, findings, err := service.prepareExecute("proj", "01", ExecuteRequest{})
	if err != nil || len(findings) != 0 || len(tasks) != 2 {
		t.Fatalf("prepare findings=%+v err=%v", findings, err)
	}
	now := time.Date(2026, 8, 20, 10, 0, 0, 0, time.UTC)
	records := ExecuteTasksToRecords(tasks, func() time.Time { return now })
	records[0].Status = ExecuteTaskRunning
	records[0].StartedAt = &now
	state := NewExecuteRunState(sp, ExecuteTargetRef{Path: "/tmp/probe-target", Source: "project-index.md"}, ArtifactRelPath(sp, StagePlan), "sha256:x", records, now)
	if err := SaveExecuteRunState(root, sp, state); err != nil {
		t.Fatal(err)
	}

	result, err := service.Execute(context.Background(), "proj", "01", ExecuteRequest{Resume: true})
	if err != nil {
		t.Fatalf("resume err=%v result=%+v", err, result)
	}
	recovered := result.Tasks[0]
	if recovered.Status != ExecuteTaskComplete || recovered.Attempts != 1 {
		t.Fatalf("task0 = %+v", recovered)
	}
	found := false
	for _, d := range recovered.Diagnostics {
		if d.Code == "stale-running" && strings.Contains(d.Message, "on resume") {
			found = true
		}
	}
	if !found {
		t.Fatalf("missing stale-running diagnostic: %+v", recovered.Diagnostics)
	}
	if len(runtime.snapshot()) != 2 {
		t.Fatalf("requests=%d", len(runtime.snapshot()))
	}
}

// R2: completed task keeps its recorded session; resume continues it for the next task.
func TestScratchResumeReusesRecordedSession(t *testing.T) {
	runtime := &resumeRuntime{}
	root, sp, service := executePersistenceFixture(t, runtime)
	twoTaskPlan(t, sp)

	_, tasks, _, _, _, err := service.prepareExecute("proj", "01", ExecuteRequest{})
	if err != nil {
		t.Fatal(err)
	}
	now := time.Date(2026, 8, 20, 10, 0, 0, 0, time.UTC)
	records := ExecuteTasksToRecords(tasks, func() time.Time { return now })
	done := now.Add(time.Hour)
	records[0].Status = ExecuteTaskComplete
	records[0].CompletedAt = &done
	records[0].Runtime = &ExecuteRuntimeSummary{SessionID: "sess-prev", Model: "test/model", ModelSource: "planning.execute_model"}
	state := NewExecuteRunState(sp, ExecuteTargetRef{Path: "/tmp/probe-target", Source: "project-index.md"}, ArtifactRelPath(sp, StagePlan), "sha256:x", records, now)
	if err := SaveExecuteRunState(root, sp, state); err != nil {
		t.Fatal(err)
	}

	result, err := service.Execute(context.Background(), "proj", "01", ExecuteRequest{Resume: true})
	if err != nil {
		t.Fatalf("resume err=%v result=%+v", err, result)
	}
	reqs := runtime.snapshot()
	if len(reqs) != 1 {
		t.Fatalf("requests=%d", len(reqs))
	}
	req := reqs[0]
	if req.SessionID != "sess-prev" || req.SessionAction != "continue" || req.Metadata["execution_session_mode"] != "continue" {
		t.Fatalf("expected continuation of sess-prev, got session=%q action=%q mode=%q", req.SessionID, req.SessionAction, req.Metadata["execution_session_mode"])
	}
	t.Logf("RESUME reuse: session=%s action=%s mode=%s prompt_head=%q", req.SessionID, req.SessionAction, req.Metadata["execution_session_mode"], truncateForLog(req.Prompt))
	if result.Tasks[0].Status != ExecuteTaskComplete || result.Tasks[1].Status != ExecuteTaskComplete {
		t.Fatalf("tasks=%+v/+%+v", result.Tasks[0], result.Tasks[1])
	}
}

// R3: checked plan marker without matching state blocks resume before any runtime call.
func TestScratchResumeCheckedMarkerWithoutStateBlocked(t *testing.T) {
	runtime := &resumeRuntime{}
	_, sp, service := executePersistenceFixture(t, runtime)
	twoTaskPlan(t, sp)
	plan := readFileContent(t, sp.Path, "plan.md")
	plan = strings.Replace(plan, "- [ ] Task 1:", "- [x] Task 1:", 1)
	writeFileContent(t, sp.Path, plan, "plan.md")

	result, err := service.Execute(context.Background(), "proj", "01", ExecuteRequest{Resume: true})
	if err == nil || !strings.Contains(err.Error(), "prerequisites failed validation") || len(result.Findings) == 0 {
		t.Fatalf("expected validation block, err=%v findings=%+v", err, result.Findings)
	}
	if len(runtime.snapshot()) != 0 {
		t.Fatalf("runtime was called despite validation failure")
	}
	if _, statErr := osStat(sp.Path + "/.run-state.json"); !osIsNotExist(statErr) {
		t.Fatalf("unexpected state file: %v", statErr)
	}
}

func truncateForLog(s string) string {
	if len(s) > 80 {
		return s[:80]
	}
	return s
}
